const DATA = {"series":[{"name":"BLAKE3","min":[0.7808934746393731,0.7851786227946815,0.781385726140815,0.7805588278661781,0.7779148320604738,0.7903655191221766,0.44237458954726044,0.43616658271810194,0.436593871185745,0.43456671578543526,0.4335719046832846,0.43260944911411825,0.4340399605887276,0.4299481335808249,0.43388652801513666],"med":[0.789984871335361,0.8063944243799539,0.7907753718459073,0.7875727054261621,0.7856014058278782,0.805258799088809,0.4507567896110057,0.44326625373365647,0.4394457720328069,0.4386220114571707,0.43802467181528215,0.4375004359654018,0.43860386439732146,0.4379118190092199,0.43866146935356987],"max":[0.9357639107992478,0.9562871548197392,0.9435252073052857,0.9511705024595924,0.9200089376168953,0.9513631769763861,0.5391535315613141,0.5276183806850203,0.5250645513119905,0.5235763549804687,0.5192561526950314,0.5173683166503906,0.5235535757882255,0.520173241110409,0.5244722366333008]},{"name":"SHA-256","min":[0.5445568594804591,0.4294765474474308,0.38526557601880873,0.37947982427176224,0.3767191796760927,0.3740282823139591,0.36386616432625146,0.37175049385948217,0.3614691468678653,0.3714638686761623,0.37144833076290973,0.3715259272877763,0.3675135170541159,0.37186946868896487,0.36846399307250977],"med":[0.5549798900540667,0.4378623987254481,0.38932494122257055,0.38210876157183016,0.3805928712553538,0.37832496732125487,0.3757440273179812,0.3743380962758235,0.3741635303700533,0.3741795609637005,0.37498008914110137,0.3743462446259289,0.3751273736721132,0.3751834392547607,0.3749986171722412],"max":[0.6662754612224072,0.5201484594832485,0.4832851684952978,0.4653211447932823,0.45437609890611314,0.4537104625182393,0.4503070089675495,0.43969252412771326,0.4499639920448059,0.4456604748237424,0.44476504442168446,0.45457309629858994,0.44932788755835557,0.4461090087890625,0.44991168975830076]},{"name":"SHA-1DC","min":[2.7436257260947277,1.8895056790610216,1.53684831858518,1.3051174079656236,1.2092854640298973,1.1880391819795568,1.1830324069619766,1.1988724812422649,1.1921651304649015,1.2455969741663981,1.2482404708862307,1.2672211329142253,1.2908561012961648,1.3092095057169597,1.339872678120931],"med":[2.814315236818588,1.9283544560536212,1.5916591985861825,1.3486261317235333,1.2605568200618964,1.2375684873888109,1.2322975496940423,1.2557027080271503,1.240089905085822,1.2655878755235181,1.2688371340433755,1.2922088305155437,1.3138453743674539,1.3391839663187664,1.3659332593282065],"max":[3.3341885891420913,2.279929277113915,1.8815125056402286,1.5805604770608859,1.4930518384070384,1.4473308510845817,1.473024264932266,1.4931078618115718,1.4538694485067734,1.501470192191527,1.5060901641845703,1.5183820724487305,1.6105249578302556,1.5891790390014648,1.6349817911783855]},{"name":"BLAKE3 SME2","min":[0.8081973251497785,0.7975482170022947,0.7869779328417138,0.7727815702364043,0.7790861903216142,0.8103967629163108,0.44370597054028876,0.44038748762726243,0.2326346797999938,0.21842138318048007,0.20887025419648714,0.20103146278694883,0.18266156824623667,0.17115615663074313,0.16498565673828125],"med":[0.8210772662151602,0.8055386904378206,0.7936073539151256,0.786120823451451,0.7852556424478125,0.8171770338519428,0.45511513840169426,0.44524820595305425,0.24050648754616125,0.2210842906564906,0.21146115389737213,0.20708340161467254,0.18413569287555973,0.1724835577465239,0.16647035425359552],"max":[0.9746123258009899,0.955344077946523,0.9514382418870039,0.9564898602374188,0.9450899155388534,0.9720799863898377,0.5506098853414648,0.5352912454044118,0.24698176000418945,0.22947383272475094,0.21888935649311625,0.21691298811403037,0.194144458305545,0.18529474167596727,0.1840374686501243]}],"x":[150.00,207.86,265.71,323.57,381.43,439.29,497.14,555.00,612.86,670.71,728.57,786.43,844.29,902.14,960.00],"labelY":[334.06,378.06,241.14,422.06],"sizes":["64 B","128 B","256 B","512 B","1 KiB","2 KiB","4 KiB","8 KiB","16 KiB","32 KiB","64 KiB","128 KiB","256 KiB","512 KiB","1 MiB"],"baseline":0,"sharedProv":6,"plotLeft":110,"plotRight":1000,"plotTop":135,"plotBottom":455,"labelGap":44,"provTop":540,"provLine":14,"takeaway":"On this machine: SHA-256 is 1.17× to 2.13× faster than BLAKE3; BLAKE3 is 1.54× to 3.56× faster than SHA-1DC; BLAKE3 SME2 matches BLAKE3 below 16 KiB and is up to 2.64× faster from there"};

const on = DATA.series.map(() => true);
const NS = "http://www.w3.org/2000/svg";

function niceBelow(v) {
  const mag = Math.pow(10, Math.floor(Math.log10(v)));
  const n = v / mag;
  return (n >= 5 ? 5 : n >= 2 ? 2 : 1) * mag;
}
function niceAbove(v) {
  const mag = Math.pow(10, Math.floor(Math.log10(v)));
  const n = v / mag;
  return (n <= 1 ? 1 : n <= 2 ? 2 : n <= 5 ? 5 : 10) * mag;
}
function fmtTick(v) {
  return v >= 10 ? v.toFixed(0) : v >= 1 ? v.toFixed(1) : v.toFixed(2);
}
function fmt2(v) { return v.toFixed(2); }
function label(i) { return DATA.sizes[i]; }

function ticks(lo, hi) {
  const out = [];
  const eLo = Math.floor(Math.log10(lo)) - 1, eHi = Math.ceil(Math.log10(hi)) + 1;
  for (let e = eLo; e <= eHi; e++) {
    for (const m of [1, 1.5, 2, 3, 5, 7]) {
      const v = m * Math.pow(10, e);
      if (v >= lo * 0.999999 && v <= hi * 1.000001) out.push(v);
    }
  }
  return out;
}

/* Mirror of takeaway_clause() in main.rs, for the visible contenders. */
function clause(i) {
  const b = DATA.series[DATA.baseline], s = DATA.series[i];
  const ratios = b.med.map((v, k) => v / s.med[k]);
  const lowest = Math.min(...ratios), highest = Math.max(...ratios);
  const TIE = 0.05, n = s.name, bn = b.name;
  const tiedLow = lowest > 1 - TIE, tiedHigh = highest < 1 + TIE;
  const x = v => v.toFixed(2) + "\u00d7";
  if (tiedLow && tiedHigh) return `${n} matches ${bn} at every size`;
  if (lowest > 1 + TIE) return `${n} is ${x(lowest)} to ${x(highest)} faster than ${bn}`;
  if (highest < 1 - TIE) return `${bn} is ${x(1 / highest)} to ${x(1 / lowest)} faster than ${n}`;
  if (tiedLow) {
    const first = ratios.findIndex(r => r > 1 + TIE);
    return `${n} matches ${bn} below ${label(first)} and is up to ${x(highest)} faster from there`;
  }
  if (tiedHigh) {
    let last = -1; ratios.forEach((r, k) => { if (r < 1 - TIE) last = k; });
    return `${bn} is up to ${x(1 / lowest)} faster than ${n} through ${label(last)}, then they match`;
  }
  const first = ratios[0] > 1 ? n : bn, lastN = ratios[ratios.length - 1] > 1 ? n : bn;
  return `${first} is faster at ${label(0)}, ${lastN} at ${label(ratios.length - 1)}`;
}

function takeaway() {
  const visible = DATA.series.map((_, i) => i).filter(i => on[i]);
  if (visible.length === 0) return "Every contender is hidden; click a name at right to show one";
  if (!on[DATA.baseline]) {
    return visible.length === 1
      ? `Showing ${DATA.series[visible[0]].name} alone`
      : `Showing ${visible.map(i => DATA.series[i].name).join(", ")}; show ${DATA.series[DATA.baseline].name} for speed ratios`;
  }
  const others = visible.filter(i => i !== DATA.baseline);
  if (others.length === 0) return `Showing ${DATA.series[DATA.baseline].name} alone`;
  return "On this machine: " + others.map(clause).join("; ");
}

function relayout() {
  const visible = DATA.series.map((_, i) => i).filter(i => on[i]);
  let lo = Infinity, hi = 0;
  for (const i of visible) {
    lo = Math.min(lo, ...DATA.series[i].min);
    hi = Math.max(hi, ...DATA.series[i].max);
  }
  if (visible.length === 0) { lo = 0.1; hi = 1; }
  const axMin = niceBelow(lo * 0.92), axMax = niceAbove(hi * 1.08);
  const lMin = Math.log(axMin), lMax = Math.log(axMax);
  const mapY = v => DATA.plotBottom - (Math.log(v) - lMin) / (lMax - lMin) * (DATA.plotBottom - DATA.plotTop);

  /* Y axis: grid lines and tick labels. */
  const axis = document.getElementById("y-axis");
  while (axis.firstChild) axis.removeChild(axis.firstChild);
  for (const v of ticks(axMin, axMax)) {
    const y = mapY(v);
    const line = document.createElementNS(NS, "line");
    line.setAttribute("x1", DATA.plotLeft); line.setAttribute("x2", DATA.plotRight);
    line.setAttribute("y1", y.toFixed(2)); line.setAttribute("y2", y.toFixed(2));
    line.setAttribute("class", "grid");
    axis.appendChild(line);
    const t = document.createElementNS(NS, "text");
    t.setAttribute("x", (DATA.plotLeft - 10).toFixed(1)); t.setAttribute("y", (y + 3.5).toFixed(2));
    t.setAttribute("class", "tick-label"); t.setAttribute("text-anchor", "end");
    t.textContent = fmtTick(v);
    axis.appendChild(t);
  }

  /* Each series: band, median line, dots, value labels. */
  DATA.series.forEach((s, i) => {
    const g = document.getElementById("series-" + i);
    g.setAttribute("data-on", on[i] ? "true" : "false");
    if (!on[i]) return;
    const X = DATA.x;
    let band = "";
    X.forEach((x, k) => { band += (k ? " L " : "M ") + x + " " + mapY(s.max[k]).toFixed(2); });
    for (let k = X.length - 1; k >= 0; k--) band += " L " + X[k] + " " + mapY(s.min[k]).toFixed(2);
    g.querySelector(".band").setAttribute("d", band + " Z");
    let med = "";
    X.forEach((x, k) => { med += (k ? " L " : "M ") + x + " " + mapY(s.med[k]).toFixed(2); });
    g.querySelector(".median").setAttribute("d", med);
    g.querySelectorAll(".dot").forEach(dot => {
      const k = +dot.getAttribute("data-size");
      dot.setAttribute("cy", mapY(s.med[k]).toFixed(2));
    });
    g.querySelectorAll(".value-label").forEach(t => {
      const k = +t.getAttribute("data-size");
      t.setAttribute("y", (mapY(s.med[k]) + +t.getAttribute("data-offset")).toFixed(2));
    });
  });

  /*
   * Right-edge labels, every contender in its slot. Each anchors level with
   * its line's last point on the current axis; a hidden contender's anchor
   * is clamped to the plot edge, so its grey label points toward where its
   * data lies. Then push overlapping labels apart and keep the stack inside
   * the plot.
   */
  const last = DATA.x.length - 1;
  const clamp = y => Math.min(DATA.plotBottom - 8, Math.max(DATA.plotTop + 8, y));
  const slots = DATA.series
    .map((s, i) => [i, clamp(mapY(s.med[last]))])
    .sort((a, b) => a[1] - b[1]);
  for (let k = 1; k < slots.length; k++) {
    slots[k][1] = Math.max(slots[k][1], slots[k - 1][1] + DATA.labelGap);
  }
  const overrun = Math.max(0, slots[slots.length - 1][1] + 20 - DATA.plotBottom);
  for (const [i, y] of slots) {
    const lab = document.getElementById("series-" + i).querySelector(".series-label");
    lab.setAttribute("transform", `translate(0 ${(y - overrun).toFixed(2)})`);
  }

  /* Elbow annotation follows the baseline's first dot. */
  const elbow = document.getElementById("elbow");
  const b = DATA.series[DATA.baseline];
  elbow.setAttribute("transform", `translate(${DATA.x[0]} ${mapY(b.med[0]).toFixed(2)})`);
  elbow.style.display = on[DATA.baseline] ? "" : "none";

  /* Provenance: visible contenders' lines close ranks after the shared lines. */
  let slot = DATA.sharedProv;
  DATA.series.forEach((s, i) => {
    document.getElementById("series-" + i).querySelectorAll(".series-prov").forEach(t => {
      if (on[i]) t.setAttribute("y", (DATA.provTop + 40 + slot++ * DATA.provLine).toFixed(1));
    });
  });

  document.getElementById("takeaway").textContent = takeaway();
}

function toggleSeries(i) {
  on[i] = !on[i];
  relayout();
}
window.toggleSeries = toggleSeries;
